language "moriarty-sherlock-draft/1";
program P {
  fn add(a: UInt, b: UInt): UInt { a + b }
  fn sub(a: UInt, b: UInt): UInt { a - b }
  fn mul(a: UInt, b: UInt): UInt { a * b }
  fn lt(a: UInt, b: UInt): Bool { a < b }
  entry add(2, 3);
}

